  const pumpWrites = () => { if (writing || closed || !writeQueue.length) return; writing = true; const item = writeQueue.shift(); let finished = false; const done = error => { if (finished) return; finished = true; writing = false; if (error) { item.reject(error); disconnect(error); } else item.resolve(); pumpWrites(); }; try { const result = stdout.write(item.frame, error => done(error)); if (result === false && stdout.once) stdout.once("error", done); } catch (error) { done(error); } };
  const pumpCommands = () => { if (closed || mutationBusy || !commandQueue.length) return; const item = commandQueue.shift(); item.started = true; mutationBusy = true; pending.set(item.requestId, item); write(item.command).catch(error => { if (pending.delete(item.requestId)) { item.settled = true; item.cleanup(); item.reject(error); } disconnect(error); }); };
