    if (raw.type === "event") return dispatchEvent(checked(EventSchema, raw, "invalid event"));
    if (raw.type === "response") { const parsed = checked(ResponseSchema, raw, "invalid response"); if (parsed.name === "protocolError") throw Object.assign(new BridgeProtocolError(parsed.error.message), { code: parsed.error.code, details: parsed.error.details }); const item = pending.get(parsed.requestId); if (!item || item.name !== parsed.name) throw new BridgeProtocolError("invalid or unknown response"); item.settled = true; pending.delete(parsed.requestId); item.cleanup(); mutationBusy = false; if (parsed.ok) item.resolve(parsed.result); else item.reject(Object.assign(new Error(parsed.error.message), { code: parsed.error.code, details: parsed.error.details })); pumpCommands(); return; }
